class Solution {
  public int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
    // the rook attacks along its row or column unless the bishop sits between them
    if (a == e && !(c == a && between(b, d, f))) return 1;
    if (b == f && !(d == b && between(a, c, e))) return 1;
    // the bishop attacks along its diagonal unless the rook sits between them on it
    if (Math.abs(c - e) == Math.abs(d - f)
        && !(Math.abs(a - c) == Math.abs(b - d)
            && Math.abs(a - e) == Math.abs(b - f)
            && between(c, a, e)
            && between(d, b, f))) return 1;
    return 2;
  }

  private boolean between(int from, int x, int to) {
    return Math.min(from, to) < x && x < Math.max(from, to);
  }
}
